def generate_signals(df: pd.DataFrame) -> pd.Series:
    # Calculate SMA(20)
    df['SMA20'] = df['close'].rolling(window=20, min_periods=20).mean()

    def calculate_position(close, sma):
        if close > sma:
            return 1
        elif close < sma:
            return -1
        else:
