def generate_signals(df: pd.DataFrame) -> pd.Series:
    # Calculate the EMA(25)
    n = 25
    ema = np.zeros(len(df))
    alpha = 2 / (n + 1)
    ema[0] = df['close'][0]
    for t in range(1, len(df)):
        ema[t] = alpha * df['close'][t] + (1 - alpha) * ema[t - 1]

    # Generate the signals
    signals = pd.Series(0, index=df.index)
    for t in df.index:
        if t >= n - 1:
            if df['close'][t] > ema[t]:
                signals[t] = 1
            elif df['close'][t] < ema[t]:
                signals[t] = -1

    return signals

