def moving_average(data, window):
    return data.rolling(window=window).mean()

def generate_signals(df: pd.DataFrame) -> pd.Series:
    ema25 = moving_average(df['close'], 25)

    # Warm-up period
    warm_up = ema25.isnull().index[0] + ema25.isnull().to_period('D').rolling(window=1).min().values

    signals = []

    for i, close in enumerate(df['close']):
        if i < warm_up:
            signals.append(0)  # Flat during warm-up
        elif close > ema25[i]:
            signals.append(1)  # Long
        elif close < ema25[i]:
            signals.append(-1)  # Short
        else:
            signals.append(0)  # Flat

    return pd.Series(signals, index=df.index)

