import numpy as np
import pandas as pd

def generate_signals(df: pd.DataFrame) -> pd.Series:
    # Initialize the signals series with zeros
    signals = pd.Series(0, index=df.index)

    # Check if both EMA(10) and EMA(20) are defined for the current bar
    def is_warm_up(ema10,ema20):
        return np.isnan(ema10) or np.isnan(ema20)

    # Compute the EMA using a recursive formula
    def compute_ema(series, alpha=0.5):
        ema = series.copy()
        ema[0] = series.iloc[0]
        for i in range(1, len(series)):
            ema[i] = alpha * series.iloc[i] + (1 - alpha) * ema[i-1]
        return ema

    # Compute EMA(10) and EMA(20)
    ema10 = compute_ema(df['close'], alpha=2/(10+1))
    ema20 = compute_ema(df['close'], alpha=2/(20+1))

    # Generate the signals based on the EMA comparison
    for i, row in df.iterrows():
        if is_warm_up(ema10.iloc[i], ema20.iloc[i]):
            continue
        elif ema10.iloc[i] > ema20.iloc[i]:
            signals.iloc[i] = 1
        elif ema10.iloc[i] < ema20.iloc[i]:
            signals.iloc[i] = -1

    return signals

