import numpy as np
import pandas as pd

def generate_signals(df: pd.DataFrame) -> pd.Series:
    def ema(series: pd.Series, n: int) -> pd.Series:
        if len(series) <= n:
            return np.zeros_like(series)

        ema_values = np.zeros_like(series)
        ema_values[0] = series.iloc[0]
        alpha = 2 / (n + 1)

        for i in range(1, len(series)):
            ema_values[i] = alpha * series.iloc[i] + (1 - alpha) * ema_values[i - 1]

        return pd.Series(ema_values, index=series.index, name=f'EMA({n})')

    ema_10 = ema(df['close'], 10)
    ema_40 = ema(df['close'], 40)

    signals = np.zeros_like(ema_10)
