        avg_gain[t] = avg_gain[t-1] + (gain[t] - avg_gain[t-1]) / 7
        avg_loss[t] = avg_loss[t-1] + (loss[t] - avg_loss[t-1]) / 7

    rsi = 100 - 100 / (1 + avg_gain / avg_loss)

    # Apply the trading strategy
    for t in range(1, len(rsi)):
        if pos[t-1] == 0:
            if rsi[t] < 32:
                pos[t] = 1
            elif rsi[t] > 68:
                pos[t] = -1
        elif pos[t-1] == 1:
            if rsi[t] > 40:
                pos[t] = 0
        elif pos[t-1] == -1:
            if rsi[t] < 40:
                pos[t] = 0

