def generate_signals(df: pd.DataFrame) -> pd.Series:
    # Calculate RSI(7)
    def compute_rsi(close):
        n = 7
        change = np.diff(close)
        avg_gain = np.zeros(n)
        avg_loss = np.zeros(n)

        for t in range(n, len(close)):
            gain = np.maximum(change[t-1], 0)
            loss = np.maximum(-change[t-1], 0)
            avg_gain[t] = avg_gain[t-1] + (gain - avg_gain[t-1]) / n
            avg_loss[t] = avg_loss[t-1] + (loss - avg_loss[t-1]) / n
            if avg_loss[t] == 0:
                rsi = 100
            else:
                rsi = 100 - 100 / (1 + avg_gain[t] / avg_loss[t])
            return rsi

    df['RSI'] = df['close'].apply(compute_rsi)
    df['signal'] = 0

    for i in range(len(df)):
        if i == 0:
            # Initial flat position
            continue
        if df.loc[i, 'RSI'] < 32:
            df.loc[i, 'signal'] = 1  # Long
        elif df.loc[i, 'RSI'] > 68:
            df.loc[i, 'signal'] = -1  # Short

        # Exit to flat if the previous position was long
        if df.loc[i-1, 'signal'] == 1 and df.loc[i, 'RSI'] > 40:
            df.loc[i, 'signal'] = 0
        # Exit to flat if the previous position was short
        elif df.loc[i-1, 'signal'] == -1 and df.loc[i, 'RSI'] < 40:
            df.loc[i, 'signal'] = 0

    return df['signal']

