            channel_bottom = find_channel_bottom(df['close'].iloc[:i])
        else:
            channel_top = find_channel_top(df['close'].iloc[i-40:i])
            channel_bottom = find_channel_bottom(df['close'].iloc[i-3:i])

        if df['position'].iloc[i-1] == 0:
            if is_breakout(df['close'].iloc[i], channel_top, 1):
                df['position'].iloc[i] = 1
                df['direction'].iloc[i] = 1

        elif df['position'].iloc[i-1] == 1:
            if is_exit(df['close'].iloc[i], channel_bottom):
                df['position'].iloc[i] = 0
                df['direction'].iloc[i] = -1

