    def find_bar_of_interest(df, window_length):
        for i in range(df.shape[0]):
            if is_within_window(i, i + window_length, df.index):
                return i

    def get_highs_lows(df, bars_of_interest, direction='high'):
        values = []
        for bar in bars_of_interest:
            if direction == 'high':
                values.append(df.at[bar, 'high'])
            else:
                values.append(df.at[bar, 'low'])
        return np.array(values)

    positions = pd.Series(0, index=df.index)

    for bar in range(df.shape[0]):
