            positions[bar] = 0
            continue

        first_high_bar_of_interest = find_bar_of_interest(df, 55)
        first_low_bar_of_interest = find_bar_of_interest(df, 6)

        if first_high_bar_of_interest is None or first_low_bar_of_interest is None:
            positions[bar] = 0
            continue

        highs = get_highs_lows(df, range(first_high_bar_of_interest, first_high_bar_of_interest + 55), 'high')
        lows = get_highs_lows(df, range(first_low_bar_of_interest, first_low_bar_of_interest + 6), 'low')

        highest_high = np.max(highs)
        lowest_low = np.min(lows)

        if positions[bar-1] == 0:
