                positions[bar] = 1
        elif positions[bar-1] == 1:
            if df.at[bar, 'close'] < df.at[first_low_bar_of_interest - 1, 'low']:
                positions[bar] = 0
        else:
            positions[bar] = positions[bar-1]

    return positions

