def generate_signals(df: pd.DataFrame) -> pd.Series:
    """
    Generates trading signals based on z-score mean reversion.

    Parameters:
    - df: pd.DataFrame with 'open', 'high', 'low', 'close', 'volume' columns and a datetime index.

    Returns:
    - pd.Series with integer target positions: 1=long, -1=short, 0=flat.
    """
    if len(df) < 30:
        return pd.Series(0, index=df.index)

    # Calculate SMA (Simple Moving Average) and STD (Standard Deviation)
    sma_30 = df['close'].rolling(window=30).mean()
    std_30 = df['close'].rolling(window=30).std()

    # Initialize position series with 0
    positions = pd.Series(0, index=df.index)

    # Calculate target z-scores
    z_score = (df['close'] - sma_30) / std_30

    # Generate signals
    for i in range(30, len(df)):
        if positions[i-1] == 0:
            if z_score[i] < -2.5:
                positions[i] = 1
            elif z_score[i] > 2.5:
                positions[i] = -1
        elif positions[i-1] == 1:
            if df['close'].iloc[i] >= sma_30:
                positions[i] = 0
        elif positions[i-1] == -1:
            if df['close'].iloc[i] <= sma_30:
                positions[i] = 0

    return positions

