            elif signals[i-1] == 1:
                if close[i] >= m - 0.5 * s:
                    signals[i] = 0
            elif signals[i-1] == -1:
                if close[i] <= m + 0.5 * s:
                    signals[i] = 0

    return pd.Series(signals, index=df.index)

