def calculate_sma(data: np.ndarray, window: int) -> pd.Series:
    """Calculate Simple Moving Average (SMA) over a given window size."""
    return pd.Series(np.convolve(data, np.ones(window) / window, 'valid'))

def calculate_std(data: np.ndarray, window: int) -> pd.Series:
    """Calculate Sample Standard Deviation (STD) over a given window size."""
    mean = calculate_sma(data, window)
    return pd.Series(np.sqrt(np.mean((data - mean) ** 2)))

