def calculate_sma(data, window):
    return data.rolling(window=window).mean()

def calculate_volatility(data, window):
    one_bar_returns = data / data.shift(1) - 1
    return one_bar_returns.rolling(window=window - 1).std()

def generate_signals(df: pd.DataFrame) -> pd.Series:
    n = 25
    m = 15
    ma_25 = calculate_sma(df['close'], n)
    vol_15 = calculate_volatility(df['one_bar_return'], m)

