        # Determine the long/short signal
        if df['close'].iloc[i] > ma_25.iloc[i]:
            signals[i] = 1
        elif df['close'].iloc[i] < ma_25.iloc[i]:
            signals[i] = -1

    return pd.Series(signals, index=df.index)

