def generate_signals(df: pd.DataFrame) -> pd.Series:
    n = 100  # Define the number of bars for the indicator
    warm_up = n

    def _signal(close):
        # Check if the indicator is defined
        if not np.all(df['high'][:n].isna()):
            # Calculate the prior N-bar highest close
            prior_n_bar_highest_close = df['high'][:n].max()
            # Check if the current close is greater than the prior N-bar highest close
            return 1  if close > prior_n_bar_highest_close else 0
        else:
            return 0

    def _stop_loss(entry_price):
        return entry_price * (1 - 0.035)

    def _take_profit(entry_price):
        return entry_price * (1 + 0.1)

    # Initialize the signal series with 0 (flat)
    signals = pd.Series(0, index=df.index)

    # Initialize the entry price variable
    entry_price = None

    # Iterate over the DataFrame
    for idx, row in df.iterrows():
        if idx < warm_up:
            # Signal is ignored while warm-up
            signals[idx] = 0
        else:
            if signals[idx - 1] == 0:  # Check if the previous position was flat
                signals[idx] = _signal(row['close'])
                if signals[idx] == 1:  # Position changed to long
                    entry_price = row['close']
            else:
                # Position is still flat
                signals[idx] = 0

            # Check if the position needs to be closed
            if signals[idx] == 1 and row['close'] <= _stop_loss(entry_price):
                signals[idx] = 0
                entry_price = None
            elif signals[idx] == 1 and row['close'] >= _take_profit(entry_price):
                signals[idx] = 0
                entry_price = None

    return signals

