        if row['close'] < entry_price:
            return -1
        # Exit when close is above the profit level
        elif row['close'] > entry_price * 1.07:
            return -1
        else:
            return 0

    # Apply the rules to generate signals
    prev_entry = -1
    for i in range(len(df)):
        if prev_entry == 1 and i == 0:
            # Skip the first bar in the position
            continue
        if prev_entry == 1:
            signals[i] = exit_rule(df.iloc[i])
            prev_entry = 0
        elif prev_entry == -1 and i == 0:
            # Skip the first bar in the position
            continue
        elif prev_entry == -1:
            signals[i] = entry_rule(df.iloc[i])
            prev_entry = 1

