def generate_signals(df: pd.DataFrame) -> pd.Series:
    def get_ema(data, span=21):
        return data.ewm(span=span, adjust=False).mean()

    def get_wma(data, span=10):
        return data.rolling(window=span).mean()

    def get_rsi(data, span=14):
        delta = data.diff()
        gain = delta.where(delta > 0, 0)
        loss = -delta.where(delta < 0, 0)

        ema_gain = get_ema(gain, span=span)
        ema_loss = get_ema(loss, span=span)

        rs = ema_gain / ema_loss
        rsi = 100 - (100 / (1 + rs))

        return rsi

    df['ema_21'] = get_ema(df['close'])
    df['ema_10'] = get_ema(df['close'], span=10)
    df['rsi'] = get_rsi(df['close'])

    # Initialize position series
    positions = pd.Series(0, index=df.index)

    entry_prices = np.nan * np.ones(len(df))

    # Warm-up period
    for i in range(len(df))[:18]:
        positions[i] = 0

    # Trading logic
    for i in range(18, len(df)):
        if positions[i-1] == 0:
            if df.at[i, 'close'] > df.at[i-18, 'ema_21']:
                positions[i] = 1
                entry_prices[i] = df.at[i, 'close']
            elif df.at[i, 'close'] < df.at[i-18, 'ema_21']:
                positions[i] = -1
                entry_prices[i] = df.at[i, 'close']
        else:
            if positions[i-1] == 1:
                if df.at[i, 'close'] <= entry_prices[i] * (1 - 0.08):
