    # Calculate hot zone variables
    hot_zone_max = df['close'].expanding(min_periods=n).max()
    hot_zone_min = df['close'].expanding(min_periods=n).min()

    # Signal generation
    for i in range(n, len(df)):
        if signals[i - 1] != 0:
            continue

        if df.at[i, 'close'] > hot_zone_max.iloc[i - n] and df.at[i - n, 'close'] > hot_zone_max.iloc[i - 1] and df.at[i - 2, 'close'] > hot_zone_max.iloc[i - 2]:
            # Long signal
            signals.at[i] = 1
        elif df.at[i, 'close'] < hot_zone_min.iloc[i - n] and df.at[i - n, 'close'] < hot_zone_min.iloc[i - 1] and df.at[i - 2, 'close'] < hot_zone_min.iloc[i - 2]:
            # Short signal
            signals.at[i] = -1

    # Calculate stop-loss and take-profit levels for existing positions
    entry_prices = df['close'].shift(1)
    for i in range(n, len(df)):
        if signals[i] != 0:
            entry_price = entry_prices.iloc[i - 1]
