def generate_signals(df: pd.DataFrame) -> pd.Series:
    """
    Generate signals for a long/short trading strategy.
    Args:
        df: DataFrame with columns 'open', 'high', 'low', 'close', 'volume' and a DatetimeIndex.
    Returns:
        Series of integer target positions with the same index as df.
    """
    # Initialize the target positions series to all zeros (flat)
    target_positions = pd.Series(0., index=df.index).astype(int)

    # Helper function to calculate max and min close within the last 24 bars
    def max_close(last_24bars):
        return max(last_24bars)

    def min_close(last_24bars):
        return min(last_24bars)

    # Warm-up period: Initialize all positions flat
    for start in range(len(df)):
        if start < 24:
            target_positions[start] = 0
        else:
            break

    # Main loop for trading
    for i in range(len(df)):
        if i >= 24:
            # Indicator calculation
            last_25_closes = df['close'].iloc[max(0, i - 25):i]

            # Signal for long when close is above 25-bar max close
            if df['close'].iloc[i] > max_close(last_25_closes):
                target_positions[i] = 1
            # Signal for short when close is below 25-bar min close
            elif df['close'].iloc[i] < min_close(last_25_closes):
                target_positions[i] = -1

            # Check if we have an open position
            if target_positions[i] != 0:
                # Calculate stop-loss and take-profit levels
                entry_price = df['close'].iloc[i]
                stop_loss = entry_price * (1 - 0.03)
                take_profit = entry_price * (1 + 0.07)

                # Exit conditions
                if df['close'].iloc[i] <= stop_loss or df['close'].iloc[i] >= take_profit:
                    target_positions[i] = 0

    return target_positions

