def generate_signals(df: pd.DataFrame) -> pd.Series:
    def rsi(data, window=10):
        changes = np.diff(data)
        avg_gain = changes[:window].copy()
        avg_loss = -changes[:window].copy()
        for i in range(window, len(changes)):
            avg_gain[i] = (avg_gain[i-1] * (window-1) + changes[i]) / window
            avg_loss[i] = (avg_loss[i-1] * (window-1) + changes[i]) / window
            rsi_val = 100 - 100 / (1 + avg_gain[i] / avg_loss[i])
            if avg_loss[i] == 0:
                rsi_val = 100
            if i < window:
                rsi_val = 100
            yield rsi_val

    rsi_values = pd.Series(rsi(df['close'], 10), index=df.index)

    signals = pd.Series(0, index=df.index)

    for i in range(len(df)):
        if i < 10 - 1:
            continue
        if rsi_values[i] < 15:
            signals[i] = 1
        if rsi_values[i] >= 15 and signals[i-1] == 1 and signals[i] == 0:
            signals[i+1:i+3] = [1, 0]
            signals[i] = 0

    return signals

