    one_bar_returns = pd.Series(index=df.index, dtype=float)

    for t in range(df.index.size):
        if warm_up and is_entry_signal(df.loc[t]):
            one_bar_returns[t] = -0.03
            warm_up = False
            exit_bar = t + 12
