    n = len(df)

    for i in range(n):
        # Calculate RSI
        change = df['close'].diff().iloc[i]
        gain = np.maximum(change, 0)
        loss = np.maximum(-change, 0)

        if i == 0:
            avg_gain = gain[1]
            avg_loss = loss[1]
        else:
            avg_gain = avg_gain + (gain[i] - avg_gain) / 14
            avg_loss = avg_loss + (loss[i] - avg_loss) / 14

        # Check if RSI is below 35
        if avg_loss == 0:
            rsi_value = np.nan
        else:
            rsi_value = 100 - (100 / (1 + avg_gain / avg_loss))

        if np.isnan(rsi_value) or rsi_value >= 35:
            continue

        # Entry signal at bar t
        if i < 4:
            continue

        # Entry signal
        signal_series[i] = 1

        # Hold for 5 bars
        for j in range(5):
            signal_series[i + j + 1] = 1

        # Ignore entry signals while position is open
        while signal_series[i + j + 1] == 1:
            j += 1
            if i + j + 1 == n:
                break

        # Start new entry after exit
        if i + j + 1 < n:
            signal_series[i + j + 1] = 1

