        if change > 0:
            gain = change
            loss = 0
        else:
            gain = 0
            loss = -change
        avg_gain = (avg_gain * (period - 1) + gain) / period
        avg_loss = (avg_loss * (period - 1) + loss) / period
        # Handle the case where avg_loss is zero to avoid division by zero
        if avg_loss == 0:
            return 0
        return 100 - (100 / (1 + avg_gain / avg_loss))

