def calculate_rsi(data, window=9):
    gains = np.where(data['close'].diff() > 0, data['close'].diff(), 0)
    losses = np.where(data['close'].diff() < 0, -data['close'].diff(), 0)

    avg_gain = np.zeros(len(data))
    avg_loss = np.zeros(len(data))

    avg_gain[window-1] = gains[window-1]
    avg_loss[window-1] = losses[window-1]

    for t in range(window, len(data)):
        avg_gain[t] = (avg_gain[t-1] * (window-1) + gains[t]) / window
        avg_loss[t] = (avg_loss[t-1] * (window-1) + losses[t]) / window

    rs = avg_gain / avg_loss
    rsi = 100 - (100 / (1 + rs))

    return pd.Series(rsi, index=data.index)

