import numpy as np
import pandas as pd

def generate_signals(df: pd.DataFrame) -> pd.Series:
    def rsi(series, window):
        avg_gain = pd.Series(0, index=series.index)
        avg_loss = pd.Series(0, index=series.index)
        for i in range(window, len(series)):
            change = series[i] - series[i-1]
            gain = np.maximum(0, change)
            loss = np.maximum(0, -change)
            avg_gain[i] = avg_gain[i-1] + (gain[i] - avg_gain[i-1]) / window
            avg_loss[i] = avg_loss[i-1] + (loss[i] - avg_loss[i-1]) / window
            if avg_loss[i] == 0:
                return pd.Series(np.nan, index=series.index[:i+1])
            rsi_value = 100 - 100 / (1 + avg_gain[i] / avg_loss[i])
            if np.isnan(rsi_value):
                return pd.Series(np.nan, index=series.index[:i+1])
            return rsi_value

    df['RSI'] = df['close'].rolling(window=4).apply(lambda x: rsi(x, 4))
    signals = pd.Series(0, index=df.index)
    prev_rsi = None
    entry_bar = None
    holding_period = 4

    for t in range(len(df)):
        if df['RSI'][t] < 22:
            if prev_rsi is None:
                prev_rsi = df['RSI'][t]
                entry_bar = t
                signals[t] = 1
            elif entry_bar is not None and signals[entry_bar] == 1:
                if t - entry_bar == holding_period - 1:
                    signals[t] = 0
                    prev_rsi = None
                    entry_bar = None
                elif t - entry_bar == holding_period:
                    signals[t] = 0
                    prev_rsi = None
                    entry_bar = None
                elif t - entry_bar < holding_period:
                    signals[t] = 1
                    continue

    return signals

