def calculate_rsi(close, window_size, smoothing_window, t):
    # Calculate the differences
    change = close[t] - close[t - 1]
    # Initialize the average gains and losses
    avg_gain = 0.0
    avg_loss = 0.0
    # Calculate the first period average gains and losses
    for i in range(1, window_size):
        if change[i - 1] > 0:
            avg_gain += change[i - 1] / window_size
        else:
            avg_loss += -change[i - 1] / window_size
    # Calculate the remaining average gains and losses
    for i in range(window_size, t):
        # Calculate the gain and loss for the current bar
        if change[i - 1] > 0:
            gain = change[i - 1]
            loss = 0
        else:
            gain = 0
            loss = -change[i - 1]
        # Update the average gains and losses
        avg_gain += (gain - avg_gain) / smoothing_window
        avg_loss += (loss - avg_loss) / smoothing_window
    # Calculate the RSI
    rsi = 100 - (100 / (1 + avg_gain / avg_loss))
    if avg_loss == 0:
        rsi = 100
    return rsi

