def generate_signals(df: pd.DataFrame) -> pd.Series:
    """
    Generates trading signals based on a long-term trend filter and an entry signal.

    Parameters:
    - df: pd.DataFrame with columns [DatetimeIndex, open, high, low, close, volume]. Indices must be sorted by time.

    Returns:
    - pd.Series of integers: 1 = long, -1 = short, 0 = flat. Index is the same as df.
    """
    # Initialize the target signals series
    signals = pd.Series(0, index=df.index)

    # Initialize the short-term and long-term SMA
    short_sma = np.zeros_like(df['close'])
    long_sma = np.zeros_like(df['close'])

    # Calculate SMA(150), SMA(20), SMA(50)
    for i in range(149, len(df)):
        short_sma[i] = np.mean(df['close'][:i + 1])  # SMA(150)
        if i < 19:
            continue
        else:
            long_sma[i] = np.mean(df['close'][:i + 1])  # SMA(20)
    for i in range(39, len(df)):
        if i < 49:
            continue
        else:
            long_sma[i] = np.mean(df['close'][:i + 1])  # SMA(50)

    # Determine the position for each bar
    for i in range(50, len(df)):
        if df['close'].iloc[i] > long_sma[i] and long_sma[i] > short_sma[i]:
            signals.iloc[i] = 1
        elif df['close'].iloc[i] > short_sma[i]:
            signals.iloc[i] = 1  # In case of ties, prefer long
        elif df['close'].iloc[i] < df['close'].iloc[i - 1] and df['close'].iloc[i] < df['close'].iloc[i - 2]:
            signals.iloc[i] = -1  # Prefer short when price is falling

    return signals

