        avg_loss = 0.0
        result = []

        for i in range(2, n + 1):
            gain = max(0, x[i] - x[i - 1])
            loss = max(0, x[i - 1] - x[i])
            avg_gain = (avg_gain * (i - 1) + gain) / i
            avg_loss = (avg_loss * (i - 1) + loss) / i
            if avg_loss == 0:
                result.append(100)
            else:
                result.append(100 - 100 / (1 + avg_gain / avg_loss))

