    def SMA(n):
        return df['close'].rolling(window=n).mean()

    def RSI(n):
        n = n + 1  # to account for the first bar
        gains = np.where(df['close'].diff() > 0, df['close'].diff(), 0)
        losses = np.where(df['close'].diff() < 0, -df['close'].diff(), 0)
        avg_gain = np.zeros(n)
        avg_loss = np.zeros(n)

        avg_gain[1] = gains[1] / n
        avg_loss[1] = losses[1] / n

        for i in range(2, n):
            avg_gain[i] = (avg_gain[i-1] + (gains[i] - avg_gain[i-1])) / n
            avg_loss[i] = (avg_loss[i-1] + (losses[i] - avg_loss[i-1])) / n

        avg_gain[n-1] = avg_gain[-1] + (gains[n-1] - avg_gain[-1]) / n
        avg_loss[n-1] = avg_loss[-1] + (losses[n-1] - avg_loss[-1]) / n

        return 100 - (100 / (1 + avg_gain / avg_loss))

    df = df.copy()
    df['sma_125'] = SMA(125)
    df['rsi_12'] = RSI(12)
    df['position'] = 0

    for t in range(df.shape[0]):
        if df.index[t] <= df.index[-125]:
