def generate_signals(df: pd.DataFrame) -> pd.Series:
    def SMA(data, n):
        return data.rolling(window=n).mean()

    def RSI(data, n):
        gain = np.where(data.diff() > 0, data.diff(), 0)
        loss = np.where(data.diff() < 0, -data.diff(), 0)
        avg_gain = gain.ewm(alpha=1/n).mean()
        avg_loss = loss.ewm(alpha=1/n).mean()
        RSI_values = 100 - 100 / (1 + avg_gain / avg_loss)
        RSI_values[avg_loss == 0] = 100
        return pd.Series(RSI_values, index=data.index)

    df['SMA_50'] = SMA(df['close'], 50)
    df['RSI_5'] = RSI(df['close'], 5)

    signals = pd.Series(0, index=df.index)

    for i in range(len(df)):
        if i == 0:
            continue  # Warm-up period
        time_since_last_signal = i - np.where(signals == df['position'].iloc[i])[0][0] if np.any(signals == df['position'].iloc[i]) else i

        if df['position'].iloc[i] == 0:
            if df['close'].iloc[i] > df['SMA_50'].iloc[i] and df['RSI_5'].iloc[i] < 20:
                signals.iloc[i] = 1
            elif df['close'].iloc[i] < df['SMA_50'].iloc[i] and df['RSI_5'].iloc[i] > 80:
                signals.iloc[i] = -1
        else:
            if df['RSI_5'].iloc[i] > 75 or df['close'].iloc[i] < df['SMA_50'].iloc[i]:
                signals.iloc[i] = 0
            elif df['RSI_5'].iloc[i] < 25 or df['close'].iloc[i] > df['SMA_50'].iloc[i]:
                signals.iloc[i] = 0

        # If no new signal within the last 10 bars, update the position to the last signal
        if time_since_last_signal >= 10 and np.any(signals != signals.iloc[i]):
            signals.iloc[i] = signals.iloc[i-1]

    return signals

