    rsi_12 = 100 - 100 / (1 + df['close'].rolling(window=12).apply(lambda x: np.mean((x[1:] - x[:-1])[(x[1:] - x[:-1]) >= 0]) / np.mean((x[1:] - x[:-1])[(x[1:] - x[:-1]) < 0]))

    strategy = np.zeros(len(df), dtype=int)

    # Initiate flat position
    # When flat: go long when close > SMA(100) and RSI(12) < 45. Go short when close < SMA(100) and RSI(12) > 55.
    strategy[0] = (df['close'].iloc[0] > ma_100.iloc[0]) & (rsi_12.iloc[0] < 45) - (df['close'].iloc[0] < ma_100.iloc[0]) & (rsi_12.iloc[0] > 55)

    for i in range(1, len(df)):
        if strategy[i-1] == 0:
            # If flat and SMA(100) and RSI(12) are defined, check for long/short conditions
            if df['close'].iloc[i] > ma_100.iloc[i] and rsi_12.iloc[i] < 45:
                strategy[i] = 1
            elif df['close'].iloc[i] < ma_100.iloc[i] and rsi_12.iloc[i] > 55:
                strategy[i] = -1
        else:
            # If not flat, check for exit conditions
            if strategy[i-1] == 1:
                if rsi_12.iloc[i] > 60 or df['close'].iloc[i] < ma_100.iloc[i]:
                    strategy[i] = 0
            elif strategy[i-1] == -1:
                if rsi_12.iloc[i] < 40 or df['close'].iloc[i] > ma_100.iloc[i]:
                    strategy[i] = 0

    return pd.Series(strategy, index=df.index)

