def generate_signals(df: pd.DataFrame) -> pd.Series:
    def sma(data, n):
        return data.rolling(window=n).mean().fillna(0)

    def rsi(data, n):
        gains = data.where(data >= data.shift(), 0).diff()
        avg_gain = gains.rolling(window=n).mean().fillna(0)
        losses = gains.where(gains < 0, 0).diff()
        avg_loss = losses.rolling(window=n).mean().fillna(0)
        rs = avg_gain / avg_loss
        return 100 - 100 / (1 + rs)

    # Initialize positions
    positions = pd.Series(0, index=df.index)

    # Compute moving averages and RSI
    sma_100 = sma(df['close'], 100)
    rsi_12 = rsi(df['close'], 12)

    # Determine initial positions
    positions[0] = np.where((sma_100[0] > df['close'][0]) & (rsi_12[0] < 45), 1, positions[0])
    positions[0] = np.where((sma_100[0] < df['close'][0]) & (rsi_12[0] > 55), -1, positions[0])

    # Compute positions for subsequent bars
    for i in range(1, len(df)):
        # Check flat condition
        current_sma_100 = sma_100[i]
        current_rsi_12 = rsi_12[i]
        current_close = df['close'][i]

        if current_sma_100 == 0 or current_rsi_12 == 0:
            positions[i] = 0
            continue

        # Update position based on current conditions
        if positions[i-1] == 0:
            if current_close > current_sma_100 and current_rsi_12 < 45:
                positions[i] = 1
            elif current_close < current_sma_100 and current_rsi_12 > 55:
                positions[i] = -1
        else:
            if current_rsi_12 > 60 or current_close < current_sma_100:
